from pathlib import Path
import json,html
J=Path('optimization/fullsite-closed-loop-20261031');rows=json.loads((J/'coverage-table.json').read_text())['rows'];prefix=J.as_posix()+'/'
def image(path,label):
 p=path.removeprefix(prefix);return f'<a href="{p}" target="_blank"><img src="{p}" loading="lazy" alt="{html.escape(label)}"></a>'
cards=[]
for r in rows:
 cards.append(f'<article data-group="{r["designGroup"]}" data-device="{r["device"]}" data-decision="{r["decision"]}"><header><b>{r["routeKey"]}</b> · {r["device"]}<span>{r["beforeScore"]} → ref {r["referenceScore"]} → {r["afterScore"]} · fidelity {r["fidelityScore"]} · {r["decision"]}</span></header><div class="triple">'+''.join('<figure><figcaption>'+label+'</figcaption>'+image(r[k],label+' '+r['routeKey'])+'</figure>'for k,label in [('beforeScreenshot','Before · real browser'),('referenceImage','Generated reference'),('afterScreenshot','After · real browser')])+f'</div><p>{html.escape(r["reason"])}</p></article>')
overlays=json.loads((J/'overlays.json').read_text())['states'];extra=[]
for s in overlays:extra.append('<details><summary>'+s['key']+' · '+s['device']+' · '+s['kind']+'</summary><div class="pair">'+image(s['beforeScreenshot'],'Before expanded/scroll')+image(s['afterScreenshot'],'After expanded/scroll')+'</div></details>')
body='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>LENS full-site visual loop evidence</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f2eb;color:#202522;font:14px/1.6 system-ui}main{max-width:1560px;margin:auto;padding:32px}h1{font:40px Georgia;color:#071e30}nav{position:sticky;top:0;z-index:2;background:#071e30;color:#fff;padding:16px;display:flex;gap:16px;flex-wrap:wrap}select,input{font:inherit;padding:7px;border-radius:4px}article,details{border:1px solid #d8d1c6;margin:24px 0;background:#fcfaf6;padding:16px}header{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.triple{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;align-items:start}figure{margin:0}figcaption{padding:8px 0;color:#61675f}img{max-width:100%;height:auto;display:block}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}video{width:min(100%,1000px)}a{color:#a34f36}article[hidden]{display:none}@media(max-width:700px){main{padding:14px}.triple{grid-template-columns:1fr}h1{font-size:30px}}</style><main><h1>LENS · 全站视觉闭环证据</h1><p>真实浏览器前后截图与真实生图参考分列。评分是AI主观视觉判断。1个入口布局采用新设计，其他布局保留并做外围统一；科学图形、数据和绘制源码保持。</p><p><a href="RESULT.md">完整中文结果</a> · <a href="coverage-table.json">逐页账本</a> · <a href="design/provenance.json">生图来源</a> · <a href="design/visual-scores.json">评分理由</a> · <a href="after/chart-preservation.json">科学保护</a></p><nav><label>布局 <select id="group"><option value="">全部</option>GROUPS</select></label><label>设备 <select id="device"><option value="">全部</option><option>desktop</option><option>mobile</option></select></label><label>决策 <select id="decision"><option value="">全部</option><option>improved</option><option>kept_with_reason</option></select></label><input id="query" placeholder="路由名称"><span id="count"></span></nav>CARDS<h2>展开与长内容</h2>OVERLAYS<h2>真实开场与操作录屏</h2><video controls preload="metadata" src="after/intro-demo.mp4"></video><p>Chromium CDP直接录制；非生成视频，不作为性能帧率证明。</p></main><script>function filter(){let n=0;document.querySelectorAll('article').forEach(a=>{a.hidden=['group','device','decision'].some(k=>document.getElementById(k).value&&a.dataset[k]!==document.getElementById(k).value)||!a.textContent.toLowerCase().includes(document.getElementById('query').value.toLowerCase());if(!a.hidden)n++;});document.getElementById('count').textContent=n+' / 186';}document.querySelectorAll('nav select,nav input').forEach(e=>e.addEventListener('input',filter));filter();</script>'''
body=body.replace('GROUPS',''.join('<option>'+g+'</option>'for g in sorted({r['designGroup']for r in rows}))).replace('CARDS',''.join(cards)).replace('OVERLAYS',''.join(extra))
(J/'gallery.html').write_text(body);print({'galleryRows':len(rows),'overlays':len(overlays)})
